// espelha um clipe (direita <-> esquerda): troca as juntas L/R e inverte as rotações em Y e Z
function mirrorPose(p) {
  const out = {};
  for (const [j, v] of Object.entries(p)) {
    const m = /^[a-z]+L$/.test(j) ? j.slice(0, -1) + 'R' : /^[a-z]+R$/.test(j) ? j.slice(0, -1) + 'L' : j;
    out[m] = Array.isArray(v) ? [v[0], -v[1], -v[2]] : v;
  }
  return out;
}
for (const n of ['claw_raise', 'slash_h', 'slash_h_back', 'slash_d', 'slash_up', 'slash_v']) {
  const c = CLIPS[n];
  if (c) CLIPS[n + '_L'] = { ...c, keys: c.keys.map((key) => ({ t: key.t, pose: mirrorPose(key.pose) })) };
}

