// ---------- locomoção travada no adversário (V4 etapa 17: o pé não "patina" andando de lado/de costas)
// guarda em cima, pernas fazendo o passo na direção certa
const GUARD_TOP = { sp: GUARD.sp, hd: GUARD.hd, sL: GUARD.sL, eL: GUARD.eL, sR: GUARD.sR, eR: GUARD.eR };
// passo lateral para a ESQUERDA do lutador: a perna esquerda abre, a direita acompanha
CLIPS.strafe_L = {
  dur: 0.8, loop: true, stride: 0.74, axis: 'left', keys: [
    k(0, { ...GUARD_TOP, h: -0.1, lL: [-0.05, 0, 0.0], kL: [0.3, 0, 0], lR: [0.05, 0, 0.0], kR: [0.3, 0, 0] }),
    k(0.25, { ...GUARD_TOP, h: -0.07, lL: [-0.2, 0, 0.62], kL: [0.8, 0, 0], lR: [0.05, 0, -0.25], kR: [0.32, 0, 0] }),
    k(0.5, { ...GUARD_TOP, h: -0.2, lL: [-0.05, 0, 0.45], kL: [0.38, 0, 0], lR: [0.05, 0, -0.45], kR: [0.38, 0, 0] }),
    k(0.75, { ...GUARD_TOP, h: -0.08, lL: [-0.05, 0, 0.22], kL: [0.32, 0, 0], lR: [-0.12, 0, 0.12], kR: [0.8, 0, 0] }),
    k(1, { ...GUARD_TOP, h: -0.1, lL: [-0.05, 0, 0.0], kL: [0.3, 0, 0], lR: [0.05, 0, 0.0], kR: [0.3, 0, 0] }),
  ],
};
CLIPS.strafe_R = { ...CLIPS.strafe_L, axis: 'right', keys: CLIPS.strafe_L.keys.map((key) => ({ t: key.t, pose: mirrorPose(key.pose) })) };
// arremesso com a mão ESQUERDA (Lírio: a direita segura a Leonora)
CLIPS.throw_l = { ...CLIPS.throw_r, keys: CLIPS.throw_r.keys.map((key) => ({ t: key.t, pose: mirrorPose(key.pose) })) };
// recuo: a caminhada tocada ao contrário, com a guarda erguida
CLIPS.walk_back = {
  ...CLIPS.walk, axis: 'back',
  keys: CLIPS.walk.keys.map((key) => ({ t: 1 - key.t, pose: { ...key.pose, ...GUARD_TOP } })).reverse(),
};

export const JOINTS = ['hip', 'sp', 'hd', 'sL', 'eL', 'sR', 'eR', 'lL', 'kL', 'lR', 'kR'];
